104	// The target reaches s both directly and through m. Removing only the longer
105	// route's edge m -> t must still show, and because that deletion detaches the
106	// whole m segment from the target's derivation, s -> m — which belonged to the
107	// before scope — is removed as well. Nothing is added.
108	func TestCompareUpstreamLineageLongRouteEdgeDeletion(t *testing.T) {
