222	// Names compare by their exact decoded value: case and surrounding spaces
223	// matter, so a relationship renamed only by case or whitespace is a real
224	// remove/add pair.
225	func TestCompareUpstreamLineageExactNameMatching(t *testing.T) {
226		before := compareDoc(t, []string{" mid ", "t"}, [][2]string{{" mid ", "t"}})
227		after := compareDoc(t, []string{" mid ", "Mid", "t"}, [][2]string{{"Mid", "t"}})
228	
229		diff, err := CompareUpstreamLineage(before, after, "t")
230		if err != nil {
231			t.Fatalf("CompareUpstreamLineage: %v", err)
232		}
233		if got, want := depPairs(diff.Added), [][2]string{{"Mid", "t"}}; !reflect.DeepEqual(got, want) {
234			t.Errorf("Added = %v, want %v", got, want)
235		}
236		if got, want := depPairs(diff.Removed), [][2]string{{" mid ", "t"}}; !reflect.DeepEqual(got, want) {
237			t.Errorf("Removed = %v, want %v", got, want)
238		}
239	}
240	
241	// An empty target is rejected without either document being inspected first:
242	// even malformed documents yield the missing-target error.
243	func TestCompareUpstreamLineageEmptyTarget(t *testing.T) {
244		_, err := CompareUpstreamLineage("not json", "also not json", "")
245		if err == nil || err.Error() != "target dataset name is required" {
246			t.Fatalf("error = %v, want target dataset name is required", err)
247		}
248	}
249	
250	// A target missing from either valid document fails the whole comparison with
251	// the target named and the offending document identified, and no partial
252	// lists.
253	func TestCompareUpstreamLineageTargetNotRegistered(t *testing.T) {
254		withT := compareDoc(t, []string{"s", "t"}, [][2]string{{"s", "t"}})
255		withoutT := compareDoc(t, []string{"s"}, nil)
256	
257		if _, err := CompareUpstreamLineage(withoutT, withT, "t"); err == nil {
258			t.Fatal("expected error when target missing from before document")
259		} else {
260			msg := err.Error()
261			if !strings.Contains(msg, "t") || !strings.Contains(msg, "before-change") {
262				t.Fatalf("error %q must name the target and the before-change document", msg)
263			}
264		}
265	
266		if _, err := CompareUpstreamLineage(withT, withoutT, "t"); err == nil {
267			t.Fatal("expected error when target missing from after document")
268		} else {
269			msg := err.Error()
270			if !strings.Contains(msg, "t") || !strings.Contains(msg, "after-change") {
271				t.Fatalf("error %q must name the target and the after-change document", msg)
272			}
273		}
274	}
275	
276	// A document that fails import validation is rejected as a whole; the error
277	// states which document (before or after) was rejected and why, and no partial
278	// difference comes back.
279	func TestCompareUpstreamLineageRejectsInvalidDocuments(t *testing.T) {
280		good := compareDoc(t, []string{"s", "t"}, [][2]string{{"s", "t"}})
281	
282		cyclic := compareDoc(t,
283			[]string{"a", "b", "t"},
284			[][2]string{{"a", "b"}, {"b", "a"}})
285		dangling := compareDoc(t,
286			[]string{"t"},
287			[][2]string{{"ghost", "t"}})
288	
289		if _, err := CompareUpstreamLineage(cyclic, good, "t"); err == nil {
290			t.Fatal("expected rejection of cyclic before document")
291		} else if msg := err.Error(); !strings.Contains(msg, "before-change") || !strings.Contains(msg, "cycle") {
292			t.Fatalf("error %q must identify the before-change document and its cycle", msg)
293		}
294	
295		if _, err := CompareUpstreamLineage(good, cyclic, "t"); err == nil {
296			t.Fatal("expected rejection of cyclic after document")
297		} else if msg := err.Error(); !strings.Contains(msg, "after-change") || !strings.Contains(msg, "cycle") {
298			t.Fatalf("error %q must identify the after-change document and its cycle", msg)
299		}
300	
301		if _, err := CompareUpstreamLineage(good, dangling, "t"); err == nil {
302			t.Fatal("expected rejection of after document with a missing edge endpoint")
303		} else if msg := err.Error(); !strings.Contains(msg, "after-change") || !strings.Contains(msg, "ghost") {
304			t.Fatalf("error %q must identify the after-change document and the ghost endpoint", msg)
305		}
306	}
307	
308	// When both documents are invalid, the before document is validated first and
309	// its rejection is the one reported. Document validation also precedes target
310	// presence checks.
311	func TestCompareUpstreamLineageValidatesBeforeFirst(t *testing.T) {
312		cyclic := compareDoc(t, []string{"a"}, [][2]string{{"a", "a"}})
313		// Target also absent from both documents; document rejection must win.
314		if _, err := CompareUpstreamLineage(cyclic, cyclic, "ghost"); err == nil {
315			t.Fatal("expected before-document rejection")
316		} else if msg := err.Error(); !strings.HasPrefix(msg, "before-change") {
317			t.Fatalf("error %q must be the before-document rejection", msg)
318		}
319	}
320	
321	// The comparison only builds throwaway graphs and never mutates or depends on
322	// the caller's own graph: passing documents round-trips through import with no
323	// shared state, and calling twice yields identical results.
324	func TestCompareUpstreamLineageDeterministic(t *testing.T) {
325		before := compareDoc(t,
326			[]string{"o", "n", "m", "t"},
327			[][2]string{{"o", "m"}, {"m", "t"}})
328		after := compareDoc(t,
329			[]string{"o", "n", "m", "t"},
330			[][2]string{{"n", "m"}, {"m", "t"}})
331	
332		first, err := CompareUpstreamLineage(before, after, "t")
333		if err != nil {
334			t.Fatalf("first comparison: %v", err)
335		}
336		second, err := CompareUpstreamLineage(before, after, "t")
337		if err != nil {
338			t.Fatalf("second comparison: %v", err)
339		}
340		if !reflect.DeepEqual(first, second) {
341			t.Fatalf("comparisons differ:\n%+v\n%+v", first, second)
342		}
343		if got, want := depPairs(first.Added), [][2]string{{"n", "m"}}; !reflect.DeepEqual(got, want) {
344			t.Errorf("Added = %v, want %v", got, want)
345		}
346		if got, want := depPairs(first.Removed), [][2]string{{"o", "m"}}; !reflect.DeepEqual(got, want) {
347			t.Errorf("Removed = %v, want %v", got, want)
348		}
349	}
