// comparison on its own, and never creates a dependency.
func TestCompareUpstreamLineageNoteValuesAreNotNames(t *testing.T) {
	before := `{"nodes":["s","t"],"note":"lone \ud800 in a note",` +
		`"edges":[{"from":"s","to":"t","note":"\udc00"}]}`
